import os
import json
import argparse

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("directory", help="directory to inventory")
    parser.add_argument("--suffix", help="optional suffix to filter files")
    args = parser.parse_args()

    inventory = inventory_directory(args.directory, args.suffix)
    print(json.dumps(inventory, indent=4))

def inventory_directory(directory, suffix=None):
    inventory = {}
    for root, dirs, files in os.walk(directory):
        for file in files:
            if suffix and not file.endswith(suffix):
                continue
            file_path = os.path.join(root, file)
            inventory[file_path] = os.path.getsize(file_path)
    return inventory

if __name__ == "__main__":
    main()

import argparse
import json


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("jsonl_file", type=argparse.FileType("r"))
    args = parser.parse_args()

    total_cents = 0
    for line_number, line in enumerate(args.jsonl_file, start=1):
        try:
            transaction = json.loads(line)
            if not transaction.get("id") or not isinstance(transaction.get("cents"), int):
                raise ValueError(f"Invalid transaction at line {line_number}")
            total_cents += transaction["cents"]
        except json.JSONDecodeError:
            print(f"Invalid JSON at line {line_number}", file=sys.stderr)
        except ValueError as e:
            print(f"Invalid transaction at line {line_number}: {e}", file=sys.stderr)

    print(total_cents)


if __name__ == "__main__":
    main()

import json
import sys

def main():
    if len(sys.argv) != 2:
        print("Usage: python quiz.py <json_file>")
        return

    try:
        with open(sys.argv[1], "r") as file:
            data = json.load(file)
    except FileNotFoundError:
        print("File not found")
        return

    score = 0
    for question in data:
        print(question["question"])
        for answer in question["answers"]:
            print(answer)
            user_answer = input().strip().lower()
            if user_answer == answer["answer"].lower():
                score += 1
                print("Correct!")
            else:
                print("Incorrect. The correct answer is:", answer["answer"])
        print()

    print("Quiz complete!")
    print("Score:", score, "/", len(data))

if __name__ == "__main__":
    main()
